SourceCode.Declaration:
/// <summary>
/// Extension of <c>LedgerJournalTable</c> to trigger the general journal posted business event.
/// </summary>
[ExtensionOf(tableStr(LedgerJournalTable))]
final class AAXLedgerJournalTable_Table_Extension
{
}

Method.Source:
/// <summary>
/// Triggers the general journal posted business event when a daily journal is posted.
/// </summary>
void update()
{
    boolean wasNotPosted = (this.orig().Posted == NoYes::No);

    next update();

    if (wasNotPosted && this.Posted == NoYes::Yes && this.JournalType == LedgerJournalType::Daily)
    {
        if (BusinessEventsConfigurationReader::isBusinessEventEnabled(classStr(AAXGeneralJournalPostedBusinessEvent)))
        {
            AAXGeneralJournalPostedBusinessEvent::newFromLedgerJournalTable(this).send();
        }
    }
}
